class SmartHome:
    def __init__(self, name):
        self.name = name
        self.devices = []

    def add_device(self, device):
        self.devices.append(device)
        print(f"Добавление девайса {device.name}")

    def remove_device(self, device_name):
        for i in range(len(self.devices)):
            if self.devices[i].name == device_name:
                print(f"Удаление девайса {self.devices[i].name}")
                self.devices.remove(self.devices[i])
                break

    def get_device(self, device_name):
        for device in self.devices:
            if device.name == device_name:
                return device
        return None

    def turn_on_all(self):
        for device in self.devices: device.is_on = True

    def turn_off_all(self):
        for device in self.devices: device.is_on = False

    def get_status_report(self):
        print("Отчёт работы устройств")
        for device in self.devices:
            device.GetStatus()
        print("\n")

    def find_devices_by_status(self, status):
        if status == True:
            print("Поиск включённых устройств")
        else:
            print("Поиск выключенных устройств")
        for device in self.devices:
            if device.is_on == status:
                print(device.name)
        print("\n")

    def show_all_devices(self):
        print("Все устройства:")
        for device in self.devices:
            print(device.name)
        print("\n")

class Device():
    def __init__(self, name):
        self.name = name
        self.is_on = False

    def __repr__(self):
        return self.Device

    def SwichOn(self):
        self.device.SwichOn()

    def SwichOff(self):
        self.device.SwichOff()

    def GetStatus(self):
        return self.getStatus()

class Light(Device):
    def __init__(self, name, brightness=0):
        super().__init__(name)
        self.brightness = brightness
        self.__temp_mapping = {
            0: "Самый слабый режим яркости",
            1: "Средний режим яркости",
            2: "Самый сильный режим яркости"
        }

    def SwitchOn(self):
        if not self.is_on:
            self.is_on = True
            print(f"{self.name} включен")
        else:
            print(f"{self.name} уже был включен")

    def SwitchOff(self):  # Убрал лишний параметр
        if self.is_on:
            self.is_on = False
            print(f"{self.name} выключен")
        else:
            print(f"{self.name} уже был выключен")

    def GetStatus(self):
        if self.is_on:
            print(f"{self.name} включен(а), яркость: {self.brightness}")
        else:
            print(f"{self.name} выключен(а)")

    def SetBrightness(self, brightness):
        self.brightness = brightness

    def getBrightness(self):
        return self.brightness

    def changeBrightness(self, new_value):
        if not self.is_on:
            print("Ошибка: Сначала включите свет")
            return self

        if new_value < 0 or new_value > 2:
            print("Ошибка: Режим яркости не поддерживается")
            return self

        self.brightness = new_value
        print(self.__temp_mapping[self.brightness])
        return self

class Termostate(Device):
    def __init__(self, name, temperature):
        super().__init__(name)
        self.temperature = temperature

    def SwitchOn(self):
        if not self.is_on:
            self.is_on = True
            print(f"{self.name} включен")
        else:
            print(f"{self.name} уже был включен")

    def SwitchOff(self, condition_light=False):
        if self.is_on:
            self.is_on = False
            print(f"{self.name} выключен")
        else:
            print(f"{self.name} уже был выключен")

    def GetStatus(self):
        if self.is_on == True:
            print(f"{self.name} включен(а), температура: {self.temperature}")
        else:
            print(f"{self.name} выключен(а)")

    def SetTemperature(self, temperature):
        self.temperature = temperature

    def getTemperature(self):
        return self.temperature

    def changeTemperature(self, new_temperature):
        if not self.is_on:
            print("Ошибка: Сначала включите кондей")
            return self
        if new_temperature < 0 or new_temperature > 30:
            print("Ошибка: Температура не поддерживается")
            return self
        self.temperature = new_temperature
        print(f"Температура изменена на {new_temperature} градусов")
        return self

class SecurityCamera(Device):
    def __init__(self, name, onRecording):
        super().__init__(name)
        self.onRecording = onRecording

    def SwitchOn(self):
        if not self.is_on:
            self.is_on = True
            print(f"{self.name} включен")
        else:
            print(f"{self.name} уже был включен")

    def SwitchOff(self, condition_light=False):
        if self.is_on:
            self.is_on = False
            print(f"{self.name} выключена")
            self.changeOnRecording()
        else:
            print(f"{self.name} уже была выключена")

    def GetStatus(self):
        if self.is_on == True:
            print(f"{self.name} включен(а)")
            status = "включена" if self.onRecording else "выключена"
            # интересная конструкция ifa
            print(f"Запись камеры '{self.name}' {status}")
        else:
            print(f"{self.name} выключен(а)")

    def SetOnRecording(self, onRecording):
        self.onRecording = onRecording

    def getOnRecording(self):
        return self.onRecording

    def changeOnRecording(self):
        if not self.is_on:
            print("Ошибка: Сначала включите камеру")
            return self

        self.onRecording = not self.onRecording
        status = "включена" if self.onRecording else "выключена"
        # интересная конструкция ifa
        print(f"Запись камеры '{self.name}' {status}")
        return self

def main():
    my_home = SmartHome("Слабоумный Дурдом")

    light = Light("Евлампий2", 1)
    termostate = Termostate("Недомерзайка2", 22)
    camera = SecurityCamera("Подглядунька2", False)

    my_home.add_device(light)
    my_home.add_device(termostate)
    my_home.add_device(camera)

    my_home.turn_on_all()
    my_home.get_status_report()

    my_home.find_devices_by_status(True)
    my_home.find_devices_by_status(False)
    my_home.show_all_devices()

main()